(function() {
  var btn = document.createElement('button');
  btn.innerHTML = '\u2191';
  btn.setAttribute('title', '\u56DE\u5230\u9876\u90E8');
  btn.style.cssText = 'position:fixed;bottom:32px;right:32px;width:46px;height:46px;border-radius:50%;background:linear-gradient(135deg,#ff6b35,#e84526);color:#fff;border:none;font-size:20px;cursor:pointer;opacity:0;transform:translateY(20px);transition:opacity 0.4s,transform 0.4s;z-index:999;box-shadow:0 4px 14px rgba(255,107,53,0.35);';
  document.body.appendChild(btn);
  window.addEventListener('scroll', function() {
    if (window.scrollY > 300) {
      btn.style.opacity = '1';
      btn.style.transform = 'translateY(0)';
    } else {
      btn.style.opacity = '0';
      btn.style.transform = 'translateY(20px)';
    }
  });
  btn.addEventListener('click', function() {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
  btn.addEventListener('mouseenter', function() {
    btn.style.transform = 'translateY(-3px) scale(1.1)';
    btn.style.boxShadow = '0 6px 20px rgba(255,107,53,0.5)';
  });
  btn.addEventListener('mouseleave', function() {
    btn.style.transform = 'translateY(0)';
    btn.style.boxShadow = '0 4px 14px rgba(255,107,53,0.35)';
  });
})();

style:
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeSlideRight {
  from { opacity: 0; transform: translateX(-20px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes shimmer {
  0% { background-position: -200% center; }
  100% { background-position: 200% center; }
}

body {
  font-family: var(--blog-font-serif);
  line-height: 1.8;
  color: var(--blog-text);
  background-color: var(--blog-bg);
  max-width: 960px;
}

#header {
  border-bottom: 2px solid var(--blog-accent);
  padding-bottom: 12px;
  animation: fadeSlideIn 0.6s ease both;
}

.postTitle {
  font-family: var(--blog-font-serif);
  position: relative;
  padding-bottom: 14px;
  background: linear-gradient(90deg, var(--blog-accent), var(--blog-accent2), var(--blog-accent));
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: shimmer 4s linear infinite, fadeSlideRight 0.6s ease both;
}
.postTitle::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 80px;
  height: 3px;
  background: linear-gradient(90deg, var(--blog-accent), transparent);
  border-radius: 2px;
}

#postBody {
  font-size: 16px;
  line-height: 1.9;
  animation: fadeSlideIn 0.8s ease 0.2s both;
}

#postBody h2 {
  margin-top: 2em;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--blog-border);
  transition: border-color 0.3s;
}
#postBody h2:hover {
  border-bottom-color: var(--blog-accent);
}

#postBody h3 {
  margin-top: 1.5em;
  color: var(--blog-accent);
  position: relative;
  padding-left: 14px;
}
#postBody h3::before {
  content: '';
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 3px;
  background: var(--blog-accent);
  border-radius: 2px;
}

#postBody table {
  border-radius: var(--blog-radius);
  overflow: hidden;
  border: 1px solid var(--blog-border);
  transition: box-shadow 0.3s;
}
#postBody table:hover {
  box-shadow: 0 4px 16px rgba(0,0,0,0.08);
}
#postBody table th {
  background: linear-gradient(135deg, var(--blog-accent), var(--blog-accent2));
  color: #fff;
  font-weight: 600;
  padding: 10px 16px;
}
#postBody table td {
  padding: 8px 16px;
  border-color: var(--blog-border);
  transition: background 0.2s;
}
#postBody table tbody tr:nth-child(even) {
  background-color: var(--blog-accent-light);
}
#postBody table tbody tr:hover {
  background-color: var(--blog-accent-light);
  box-shadow: inset 3px 0 0 var(--blog-accent);
}

#postBody code {
  background: var(--blog-accent-light);
  border-radius: 4px;
  padding: 2px 6px;
  font-size: 0.9em;
  color: var(--blog-accent);
}

#postBody pre {
  border-radius: var(--blog-radius);
  border: 1px solid var(--blog-border);
  transition: border-color 0.3s;
}
#postBody pre:hover {
  border-color: var(--blog-accent);
}

#postBody blockquote {
  border-left: 4px solid var(--blog-accent);
  background: var(--blog-accent-light);
  border-radius: 0 var(--blog-radius) var(--blog-radius) 0;
  padding: 12px 16px;
  margin: 16px 0;
  color: var(--blog-text-secondary);
}

#postBody img {
  border-radius: var(--blog-radius);
  box-shadow: var(--blog-card-shadow);
  transition: transform 0.3s, box-shadow 0.3s;
}
#postBody img:hover {
  transform: scale(1.02);
  box-shadow: 0 8px 24px rgba(0,0,0,0.12);
}

.title-right a, .title-right button {
  transition: transform 0.3s, color 0.3s;
}
.title-right a:hover, .title-right button:hover {
  transform: scale(1.15);
  color: var(--blog-accent) !important;
}

#footer {
  border-top: 1px solid var(--blog-border);
  padding-top: 20px;
  color: var(--blog-text-secondary);
  animation: fadeSlideIn 0.6s ease 0.4s both;
}
#footer a {
  color: var(--blog-accent);
  text-decoration: none;
  transition: opacity 0.2s;
}
#footer a:hover {
  opacity: 0.7;
}

@media (max-width: 600px) {
  body { padding: 12px; }
  .postTitle { font-size: 24px; }
}

::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--blog-border); border-radius: 3px; }

